import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicIntegerFieldUpdater;
import java.util.concurrent.atomic.LongAdder;

public class ConcurrencyDemo {
    private final AtomicInteger requestCount = new AtomicInteger(0);
    private final AtomicReference<String> currentConfig = new AtomicReference<>("v1");
    private final LongAdder globalMetricsCounter = new LongAdder();

    private static final AtomicIntegerFieldUpdater<UserSession> sessionUpdater =
        AtomicIntegerFieldUpdater.newUpdater(UserSession.class, "activeConnections");

    public void handleRequest() {
        requestCount.incrementAndGet();
        globalMetricsCounter.add(1);
    }

    public boolean updateConfig(String expected, String update) {
        return currentConfig.compareAndSet(expected, update);
    }

    public void updateConnections(UserSession session, int delta) {
        sessionUpdater.addAndGet(session, delta);
    }

    public static class UserSession {
        volatile int activeConnections;
    }
}
